motions.css:
/* 角度を登録して、conic-gradient の枠を回す */
@property --ms-angle {
  syntax: "<angle>";
  inherits: false;
  initial-value: 0deg;
}
.ms-spinning-border {
  border: 2px solid transparent;
  border-radius: 0.75rem;
  background:
    linear-gradient(var(--card), var(--card)) padding-box,
    conic-gradient(from var(--ms-angle), color-mix(in oklab, var(--primary) 85%, transparent), transparent 35%, color-mix(in oklab, var(--brand-accent) 85%, transparent) 65%, transparent) border-box;
  animation: ms-spinning-border 4.5s linear infinite;
}
@keyframes ms-spinning-border {
  to {
    --ms-angle: 360deg;
  }
}
@media (prefers-reduced-motion: reduce) {
  .ms-spinning-border {
    animation: none;
  }
}

.ms-shimmer-text {
  background-image: linear-gradient(100deg, var(--foreground) 25%, color-mix(in oklab, var(--primary) 75%, transparent) 50%, var(--foreground) 75%);
  background-size: 220% 100%;
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  animation: ms-shimmer-text 3.2s linear infinite;
}
@keyframes ms-shimmer-text {
  from {
    background-position: 120% 0;
  }
  to {
    background-position: -120% 0;
  }
}
@media (prefers-reduced-motion: reduce) {
  .ms-shimmer-text {
    animation: none;
    background-image: none;
    color: var(--foreground);
  }
}

@keyframes ms-scroll-reveal {
  from {
    opacity: 0;
    transform: translateY(1.5rem);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
@supports (animation-timeline: view()) {
  .ms-scroll-reveal {
    animation: ms-scroll-reveal linear both;
    animation-timeline: view();
    animation-range: entry 0% cover 40%;
  }
}
@media (prefers-reduced-motion: reduce) {
  .ms-scroll-reveal {
    animation: none;
    opacity: 1;
    transform: none;
  }
}

.ms-reading-progress {
  display: none;
}
@supports (animation-timeline: scroll(root)) {
  .ms-reading-progress {
    display: block;
    position: fixed;
    inset: 0 0 auto 0;
    height: 0.25rem;
    transform: scaleX(0);
    transform-origin: left center;
    background-color: var(--primary);
    animation: ms-reading-progress linear both;
    animation-timeline: scroll(root);
  }
}
@keyframes ms-reading-progress {
  from {
    transform: scaleX(0);
  }
  to {
    transform: scaleX(1);
  }
}
@media (prefers-reduced-motion: reduce) {
  .ms-reading-progress {
    animation: none;
    transform: scaleX(1);
  }
}

.ms-entry-pop {
  position: fixed;
  inset: 0;
  width: min(20rem, calc(100% - 2rem));
  height: fit-content;
  margin: auto;
  padding: 1rem 1.25rem;
  border: 1px solid var(--border);
  border-radius: 0.75rem;
  background-color: var(--card);
  color: var(--card-foreground);
  box-shadow: 0 12px 32px color-mix(in oklab, var(--foreground) 18%, transparent);
  opacity: 0;
  transform: translateY(0.75rem) scale(0.98);
  transition:
    opacity 220ms ease-out,
    transform 220ms ease-out,
    display 220ms allow-discrete,
    overlay 220ms allow-discrete;
  transition-behavior: allow-discrete;
}
.ms-entry-pop:popover-open {
  opacity: 1;
  transform: translateY(0) scale(1);
}
@starting-style {
  .ms-entry-pop:popover-open {
    opacity: 0;
    transform: translateY(0.75rem) scale(0.98);
  }
}
@media (prefers-reduced-motion: reduce) {
  .ms-entry-pop {
    transition: none;
  }
}

.ms-spring-press {
  padding: 0.75rem 1.5rem;
  border-radius: 0.75rem;
  background-color: var(--primary);
  color: var(--primary-foreground);
  transition: transform 520ms linear(0, 0.32 15%, 0.58 30%, 0.82 45%, 0.96 60%, 1.02 75%, 1);
}
.ms-spring-press:active {
  transform: scale(0.9);
  transition-duration: 120ms;
}
@media (prefers-reduced-motion: reduce) {
  .ms-spring-press {
    transition: none;
  }
}

.ms-stagger > * {
  opacity: 0;
  transform: translateY(0.75rem);
  animation: ms-stagger 420ms ease-out forwards;
}
@supports (animation-delay: calc(sibling-index() * 1ms)) {
  .ms-stagger > * {
    animation-delay: calc((sibling-index() - 1) * 90ms);
  }
}
@keyframes ms-stagger {
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
@media (prefers-reduced-motion: reduce) {
  .ms-stagger > * {
    animation: none;
    opacity: 1;
    transform: none;
  }
}

@property --ms-aurora-x {
  syntax: "<percentage>";
  inherits: false;
  initial-value: 20%;
}
@property --ms-aurora-y {
  syntax: "<percentage>";
  inherits: false;
  initial-value: 30%;
}
.ms-aurora {
  background-color: var(--background);
  background-image:
    radial-gradient(circle at var(--ms-aurora-x) var(--ms-aurora-y), color-mix(in oklab, var(--primary) 48%, transparent), transparent 60%),
    radial-gradient(circle at calc(100% - var(--ms-aurora-x)) calc(100% - var(--ms-aurora-y)), color-mix(in oklab, var(--brand-accent) 42%, transparent), transparent 62%);
  animation: ms-aurora 18s ease-in-out infinite alternate;
}
@keyframes ms-aurora {
  from {
    --ms-aurora-x: 20%;
    --ms-aurora-y: 30%;
  }
  to {
    --ms-aurora-x: 78%;
    --ms-aurora-y: 68%;
  }
}
@media (prefers-reduced-motion: reduce) {
  .ms-aurora {
    animation: none;
  }
}

.ms-skeleton-shimmer {
  position: relative;
  overflow: hidden;
  border-radius: 0.75rem;
  background-color: var(--muted);
}
.ms-skeleton-shimmer::after {
  content: '';
  position: absolute;
  inset: 0;
  background-image: linear-gradient(90deg, transparent, color-mix(in oklab, var(--foreground) 16%, transparent), transparent);
  background-size: 200% 100%;
  background-position: 150% 0;
  animation: ms-skeleton-shimmer 1.6s ease-in-out infinite;
}
@keyframes ms-skeleton-shimmer {
  to {
    background-position: -150% 0;
  }
}
@media (prefers-reduced-motion: reduce) {
  .ms-skeleton-shimmer::after {
    animation: none;
    background-position: 50% 0;
  }
}

.ms-line-draw path,
.ms-line-draw circle {
  fill: none;
  stroke: var(--primary);
  stroke-width: 3;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-dasharray: 1;
  stroke-dashoffset: 1;
  animation: ms-line-draw 2.4s ease-in-out infinite;
}
@keyframes ms-line-draw {
  0% {
    stroke-dashoffset: 1;
  }
  60% {
    stroke-dashoffset: 0;
  }
  100% {
    stroke-dashoffset: 0;
  }
}
@media (prefers-reduced-motion: reduce) {
  .ms-line-draw path,
  .ms-line-draw circle {
    animation: none;
    stroke-dashoffset: 0;
  }
}

.ms-blob {
  width: 9rem;
  height: 9rem;
  background-image: linear-gradient(140deg, color-mix(in oklab, var(--primary) 70%, transparent), color-mix(in oklab, var(--brand-accent) 65%, transparent));
  border-radius: 42% 58% 63% 37% / 41% 44% 56% 59%;
  animation: ms-blob 9s ease-in-out infinite alternate;
}
@keyframes ms-blob {
  0% {
    border-radius: 42% 58% 63% 37% / 41% 44% 56% 59%;
  }
  50% {
    border-radius: 58% 42% 37% 63% / 56% 59% 41% 44%;
  }
  100% {
    border-radius: 50% 50% 62% 38% / 48% 38% 62% 52%;
  }
}
@media (prefers-reduced-motion: reduce) {
  .ms-blob {
    animation: none;
  }
}

.ms-marquee {
  overflow: hidden;
}
.ms-marquee__track {
  display: flex;
  width: max-content;
  animation: ms-marquee 16s linear infinite;
}
.ms-marquee__group {
  display: flex;
  flex-shrink: 0;
  gap: 2rem;
  padding-right: 2rem;
}
@keyframes ms-marquee {
  from {
    transform: translateX(0);
  }
  to {
    transform: translateX(-50%);
  }
}
@media (prefers-reduced-motion: reduce) {
  .ms-marquee__track {
    animation: none;
  }
}
